const __pageData = JSON.parse('{"title":"Scott Bessent","description":"","frontmatter":{"title":"Scott Bessent","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["treasury","bessent","sanctions","venezuela","banking"],"sources":["raw/badlands-brief-02a.md","raw/badlands-brief-169.md","raw/badlands-brief-577.md","raw/badlands-brief-6bf.md","raw/badlands-brief-6f4.md","raw/badlands-brief-959.md","raw/badlands-brief-b74.md","raw/badlands-brief-a1a.md","raw/badlands-brief-bdc.md","raw/badlands-brief-c07.md","raw/badlands-brief-da2.md","raw/badlands-brief-d17.md","raw/badlands-brief-e9a.md","raw/badlands-brief-f02.md","raw/badlands-brief-f62.md","raw/badlands-brief-fa4.md","raw/badlands-news-brief-02a.md","raw/badlands-news-brief-065.md","raw/badlands-news-brief-071.md","raw/badlands-news-brief-11d.md","raw/badlands-news-brief-144.md","raw/badlands-news-brief-201.md","raw/badlands-news-brief-222.md","raw/badlands-news-brief-351.md","raw/badlands-news-brief-3a5.md","raw/badlands-news-brief-448.md","raw/badlands-news-brief-497.md","raw/badlands-news-brief-4cf.md","raw/badlands-news-brief-508.md","raw/badlands-news-brief-52f.md","raw/badlands-news-brief-58e.md","raw/badlands-news-brief-5c8.md","raw/badlands-news-brief-71f.md","raw/badlands-news-brief-669.md","raw/badlands-news-brief-745.md","raw/badlands-news-brief-7e8.md","raw/badlands-news-brief-80e.md"],"confidence":"medium"},"headers":[],"relativePath":"entities/scott-bessent.md","filePath":"entities/scott-bessent.md","lastUpdated":null}');
